import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that provides a space-efficient probabilistic data structure.

    The filtering algorithm calculates the optimal bit array size and number of hash functions
    based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array (m)
        self.size = self.optimal_size(expected_items, false_positive_rate)
        # Calculate the optimal number of hash functions (k)
        self.hash_count = self.optimal_hash_count(self.size, expected_items)

        # Initialize the bit array
        self.bit_array = [0] * self.size

    def optimal_size(self, n: int, p: float) -> int:
        """Calculates the optimal size of the bit array."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def optimal_hash_count(self, m: int, n: int) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, int(m / n * math.log(2)))

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter."""
        for i in range(self.hash_count):
            digest = self.hash(item, i)
            self.bit_array[digest] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item is possibly in the Bloom Filter."""
        for i in range(self.hash_count):
            digest = self.hash(item, i)
            if self.bit_array[digest] == 0:
                return False
        return True

    def hash(self, item: str, seed: int) -> int:
        """Creates a hash for the item using a seed to differentiate hash functions."""
        hash_input = f"{item}{seed}".encode('utf-8')
        hash_output = hashlib.sha256(hash_input).hexdigest()
        return int(hash_output, 16) % self.size

