import hashlib
import math

class BloomFilter:
    """
    A probabilistic data structure that allows for fast membership testing with a tunable false positive rate.

    This implementation chooses an alternative hashing strategy and leverages a dynamic bit array
    where the size and number of hash functions are derived from expected items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate bit array size and number of hash functions
        self.size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._calculate_hash_count(self.size, expected_items)

        # Initialize the bit array dynamically with an integer representing bits
        self.bit_array = 0

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the size of the bit array based on items and the desired false positive rate."""
        return max(1, int(-n * math.log(p) / (math.log(2) ** 2)))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Determine the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter using multiple hash functions."""
        for i in range(self.hash_count):
            digest = self._hash(item, i)
            self.bit_array |= (1 << digest)

    def contains(self, item: str) -> bool:
        """Check if an item might be in the Bloom Filter."""
        for i in range(self.hash_count):
            digest = self._hash(item, i)
            if not (self.bit_array & (1 << digest)):
                return False
        return True

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash based on the item and a seed to optimize the index calculation."""
        hash_input = f"{item}:{seed}".encode('utf-8')
        hash_output = hashlib.blake2b(hash_input).hexdigest()
        return int(hash_output, 16) % self.size
